"use client";

import Image from "next/image";
import { useCallback, useEffect, useRef, useState } from "react";
import ColorWheel from "./ColorWheel";

/** @typedef {import("../../types").StickerLibraryItem} StickerLibraryItem */
/** @typedef {import("../../types").SheetSticker} SheetSticker */
/** @typedef {import("../../types").StickerStoreState} StickerStoreState */

/**
 * @typedef {object} StickerInteraction
 * @property {string} id
 * @property {"move" | "resize" | "rotate"} mode
 * @property {number} startX
 * @property {number} startY
 * @property {number} originalX
 * @property {number} originalY
 * @property {number} originalSize
 * @property {number} originalRotation
 * @property {number} sheetWidth
 * @property {number} sheetHeight
 */

const MIN_SIZE = 5;
const MAX_SIZE = 75;

/**
 * @param {object} props
 * @param {SheetSticker[]} props.stickers
 * @param {StickerStoreState["setStickers"]} props.setStickers
 * @param {string} props.backgroundColor
 * @param {(color: string) => void} props.setBackgroundColor
 */
export default function StickerSheet({
  stickers,
  setStickers,
  backgroundColor,
  setBackgroundColor,
}) {
  const sheetRef = useRef(/** @type {HTMLDivElement | null} */ (null));
  const trashRef = useRef(/** @type {HTMLDivElement | null} */ (null));

  const [selectedId, setSelectedId] = useState(
    /** @type {string | null} */ (null)
  );
  const [interaction, setInteraction] = useState(
    /** @type {StickerInteraction | null} */ (null)
  );

  // Find den sticker, der er valgt
  const selectedSticker = stickers.find(
    (sticker) => sticker.id === selectedId
  );

  // Fjern en sticker fra A4-arket
  const deleteSticker = useCallback((/** @type {string} */ id) => {
    setStickers((current) =>
      current.filter((sticker) => sticker.id !== id)
    );

    setSelectedId(null);
  }, [setStickers, setSelectedId]);

  // Slet den valgte sticker med Delete eller Backspace
  useEffect(() => {
    /** @param {KeyboardEvent} event */
    function handleKeyDown(event) {
      const tagName = event.target?.tagName;

      if (
        tagName === "INPUT" ||
        tagName === "TEXTAREA" ||
        tagName === "SELECT"
      ) {
        return;
      }

      if (
        (event.key === "Delete" || event.key === "Backspace") &&
        selectedId
      ) {
        deleteSticker(selectedId);
      }
    }

    window.addEventListener("keydown", handleKeyDown);

    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [selectedId, deleteSticker]);

  /**
   * @param {import("react").PointerEvent<HTMLElement>} event
   * @param {SheetSticker} sticker
   * @param {"move" | "resize" | "rotate"} mode
   */
  function startInteraction(event, sticker, mode) {
    event.preventDefault();
    event.stopPropagation();

    setSelectedId(sticker.id);

    const sheet = sheetRef.current;

    if (!sheet) return;

    const rect = sheet.getBoundingClientRect();

    setInteraction({
      id: sticker.id,
      mode,
      startX: event.clientX,
      startY: event.clientY,
      originalX: sticker.x,
      originalY: sticker.y,
      originalSize: sticker.size,
      originalRotation: sticker.rotation ?? 0,
      sheetWidth: rect.width,
      sheetHeight: rect.height,
    });

    sheet.setPointerCapture(event.pointerId);
  }

  // Flyt eller rediger den aktive sticker
  /** @param {import("react").PointerEvent<HTMLDivElement>} event */
  function handlePointerMove(event) {
    if (!interaction) return;

    const {
      id,
      mode,
      startX,
      startY,
      originalX,
      originalY,
      originalSize,
      originalRotation,
      sheetWidth,
      sheetHeight,
    } = interaction;

    const deltaX = event.clientX - startX;
    const deltaY = event.clientY - startY;

    setStickers((current) =>
      current.map((sticker) => {
        if (sticker.id !== id) return sticker;

        if (mode === "move") {
          return {
            ...sticker,
            x: originalX + (deltaX / sheetWidth) * 100,
            y: originalY + (deltaY / sheetHeight) * 100,
          };
        }

        if (mode === "resize") {
          const change = (deltaX - deltaY) / 2;

          return {
            ...sticker,
            size: Math.min(
              MAX_SIZE,
              Math.max(MIN_SIZE, originalSize + change)
            ),
          };
        }

        if (mode === "rotate") {
          return {
            ...sticker,
            rotation: originalRotation + deltaX,
          };
        }

        return sticker;
      })
    );
  }

  // Afslut bevægelsen og undersøg, om stickeren blev sluppet i papirkurven
  function handlePointerUp(event) {
    if (!interaction) return;

    const trash = trashRef.current;

    if (interaction.mode === "move" && trash) {
      const rect = trash.getBoundingClientRect();

      const droppedInTrash =
        event.clientX >= rect.left &&
        event.clientX <= rect.right &&
        event.clientY >= rect.top &&
        event.clientY <= rect.bottom;

      if (droppedInTrash) {
        deleteSticker(interaction.id);
      }
    }

    setInteraction(null);
  }

  // Tilføj en sticker fra galleriet
  function addSticker(sticker) {
    const newSticker = {
      ...sticker,
      id: crypto.randomUUID(),
      x: 50,
      y: 50,
      size: 18,
      rotation: 0,
    };

    setStickers((current) => [...current, newSticker]);
    setSelectedId(newSticker.id);
  }

  // Modtag stickers via drag-and-drop fra galleriet
  function handleDrop(event) {
    event.preventDefault();

    const data = event.dataTransfer.getData("application/json");

    if (!data) return;

    try {
      const sticker = JSON.parse(data);
      addSticker(sticker);
    } catch (error) {
      console.error("Kunne ikke tilføje sticker:", error);
    }
  }

  return (
    <div className="w-full">
      <div className="mb-5 flex items-center justify-between">
        <div>
          <h3 className="font-heading text-2xl">
            Your sticker sheet
          </h3>

          <p className="text-sm text-[var(--color-text-light)]">
            Arrange your stickers and create your own design.
          </p>
        </div>

        <span className="text-xs uppercase tracking-widest text-[var(--color-text-light)]">
          A4 · 210 × 297 mm
        </span>
      </div>

      {/* A4-arket */}
      <div
        ref={sheetRef}
        data-a4-sheet
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={() => setInteraction(null)}
        onDragOver={(event) => event.preventDefault()}
        onDrop={handleDrop}
        onPointerDown={(event) => {
          if (event.target === event.currentTarget) {
            setSelectedId(null);
          }
        }}
        className="relative mx-auto w-full overflow-visible rounded-sm shadow-xl touch-none"
        style={{
          aspectRatio: "210 / 297",
          backgroundColor,
        }}
      >
        {stickers.map((sticker) => (
          <div
            key={sticker.id}
            data-sticker
            onPointerDown={(event) =>
              startInteraction(event, sticker, "move")
            }
            onClick={() => setSelectedId(sticker.id)}
            className="absolute flex cursor-grab items-center justify-center active:cursor-grabbing"
            style={{
              left: `${sticker.x}%`,
              top: `${sticker.y}%`,
              width: `${sticker.size}%`,
              aspectRatio: "1",
              transform: `translate(-50%, -50%) rotate(${sticker.rotation ?? 0}deg)`,
              zIndex: selectedId === sticker.id ? 20 : 10,
            }}
          >
            <img
              src={sticker.src}
              alt={sticker.name}
              draggable="false"
              className="pointer-events-none h-full w-full select-none object-contain"
            />

            {selectedId === sticker.id && (
              <>
                <div className="pointer-events-none absolute inset-0 border border-dashed border-[var(--color-primary-dark)]" />

                {/* Rotationshåndtag */}
                <button
                  type="button"
                  aria-label="Rotate sticker"
                  onPointerDown={(event) =>
                    startInteraction(event, sticker, "rotate")
                  }
                  className="absolute -top-7 left-1/2 flex h-6 w-6 -translate-x-1/2 items-center justify-center rounded-full border border-[var(--color-primary-dark)] bg-white text-sm shadow"
                >
                  ↻
                </button>

                {/* Størrelseshåndtag */}
                <button
                  type="button"
                  aria-label="Resize sticker"
                  onPointerDown={(event) =>
                    startInteraction(event, sticker, "resize")
                  }
                  className="absolute -bottom-2 -right-2 h-4 w-4 rounded-full border-2 border-white bg-[var(--color-primary-dark)] shadow"
                />
              </>
            )}
          </div>
        ))}
      </div>

      {/* Papirkurv */}
      <div
        ref={trashRef}
        className="mx-auto mt-8 flex min-h-20 w-full max-w-[180px] flex-col items-center justify-center rounded-2xl border-2 border-dashed border-[var(--color-border)] bg-white p-4 text-center transition"
      >
        <span className="text-2xl">🗑️</span>
        <span className="mt-1 text-sm font-medium">
          Drop here to delete
        </span>
      </div>

      {/* Redigeringsknapper */}
      <div className="mt-6 flex flex-wrap items-center justify-between gap-3">
        <p className="text-sm text-[var(--color-text-light)]">
          {selectedSticker
            ? `Selected: ${selectedSticker.name}`
            : "Select a sticker to edit"}
        </p>

        <div className="flex gap-2">
          <button
            type="button"
            disabled={!selectedId}
            onClick={() => selectedId && deleteSticker(selectedId)}
            className="rounded-full border border-[var(--color-border)] px-4 py-2 text-sm transition hover:bg-[var(--color-background)] disabled:cursor-not-allowed disabled:opacity-40"
          >
            Delete selected
          </button>

          <button
            type="button"
            disabled={stickers.length === 0}
            onClick={() => {
              setStickers([]);
              setSelectedId(null);
            }}
            className="rounded-full border border-[var(--color-border)] px-4 py-2 text-sm transition hover:bg-[var(--color-background)] disabled:cursor-not-allowed disabled:opacity-40"
          >
            Clear sheet
          </button>
        </div>
      </div>

      {/* Baggrundsfarve */}
      <div className="mt-8">
        <ColorWheel
          backgroundColor={backgroundColor}
          setBackgroundColor={setBackgroundColor}
        />
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import StickerCard from "./StickerCard";
import { useStickerStore } from "../../store/stickerStore";

const mainCategories = ["doodles", "icons", "illustrations"];

export default function StickerGallery({
  onSelectSticker,
  showManagement = false,
}) {
  const library = useStickerStore((state) => state.library);
  const favorites = useStickerStore((state) => state.favorites);
  const toggleFavorite = useStickerStore((state) => state.toggleFavorite);

  const hiddenStickerIds = useStickerStore(
    (state) => state.hiddenStickerIds
  );

  const hideStickerFromGallery = useStickerStore(
    (state) => state.hideStickerFromGallery
  );

  const restoreStickerToGallery = useStickerStore(
    (state) => state.restoreStickerToGallery
  );

  const setLibrary = useStickerStore((state) => state.setLibrary);

  const [categories, setCategories] = useState([]);

  const [category, setCategory] = useState("All");
  const [browsePath, setBrowsePath] = useState(null);

  const [searchTerm, setSearchTerm] = useState("");
  const [showHidden, setShowHidden] = useState(false);

  const [file, setFile] = useState(null);
  const [uploadCategory, setUploadCategory] = useState("doodles");

  const [parentCategory, setParentCategory] = useState("doodles");
  const [newCategory, setNewCategory] = useState("");

  const [uploading, setUploading] = useState(false);
  const [creatingCategory, setCreatingCategory] = useState(false);
  const [loadingLibrary, setLoadingLibrary] = useState(true);

  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState("info");

  // FORMAT CATEGORY LABEL
  function formatCategory(value) {
    return value
      .split("/")
      .map((part) =>
        part
          .replace(/[-_]/g, " ")
          .replace(/\b\w/g, (letter) => letter.toUpperCase())
      )
      .join(" / ");
  }

  // LOAD STICKERS AND CATEGORIES
  const loadLibrary = useCallback(async () => {
    try {
      const response = await fetch("/api/stickers", {
        cache: "no-store",
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || "Could not load stickers.");
      }

      setLibrary(result.stickers || []);
      setCategories(result.categories || []);

      return true;
    } catch (error) {
      setMessage(error.message || "Could not load the sticker library.");
      setMessageType("error");
      return false;
    } finally {
      setLoadingLibrary(false);
    }
  }, [setLibrary]);

  useEffect(() => {
    void Promise.resolve().then(loadLibrary);
  }, [loadLibrary]);

  // HIDE STICKERS WITHOUT DELETING FILES
  const visibleStickers = useMemo(
    () =>
      library.filter(
        (sticker) => !hiddenStickerIds.includes(sticker.id)
      ),
    [library, hiddenStickerIds]
  );

  const hiddenStickers = useMemo(
    () =>
      library.filter((sticker) =>
        hiddenStickerIds.includes(sticker.id)
      ),
    [library, hiddenStickerIds]
  );

  // CATEGORY OPTIONS FOR UPLOAD AND CREATION
  const categoryOptions = useMemo(
    () =>
      categories
        .filter((item) => item.value.includes("/"))
        .sort((a, b) => a.value.localeCompare(b.value)),
    [categories]
  );

  // FIND CATEGORY ROWS FOR THE SELECTED PATH
  const categoryRows = useMemo(() => {
    if (!browsePath) return [];

    const parts = browsePath.split("/");
    const rows = [];

    for (let i = 0; i < parts.length; i++) {
      const parentPath = parts.slice(0, i + 1).join("/");

      const children = categories.filter((item) => {
        const itemParts = item.value.split("/");
        const itemParent = itemParts.slice(0, -1).join("/");

        return itemParent === parentPath;
      });

      if (children.length > 0) {
        rows.push({
          parent: parentPath,
          items: children,
        });
      }
    }

    return rows;
  }, [categories, browsePath]);

  // FILTER STICKERS
  const filteredStickers = useMemo(() => {
    return visibleStickers.filter((sticker) => {
      const stickerCategory =
        sticker.categoryPath || sticker.category;

      const matchesCategory =
        category === "All"
          ? browsePath
            ? stickerCategory === browsePath
            : false
          : category === "Favorites"
            ? favorites.includes(sticker.id)
            : stickerCategory === category;

      const matchesSearch = sticker.name
        .toLowerCase()
        .includes(searchTerm.toLowerCase());

      return matchesCategory && matchesSearch;
    });
  }, [
    visibleStickers,
    favorites,
    category,
    browsePath,
    searchTerm,
  ]);

  const filteredHiddenStickers = hiddenStickers.filter((sticker) =>
    sticker.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // OPEN A CATEGORY
  function openCategory(categoryPath) {
    setBrowsePath(categoryPath);
    setCategory("All");
    setSearchTerm("");
  }

  // SELECT MAIN CATEGORY
  function selectMainCategory(categoryPath) {
    setBrowsePath(categoryPath);
    setCategory("All");
    setSearchTerm("");
  }

  // SELECT FILE
  function handleFileChange(event) {
    const selectedFile = event.target.files?.[0] || null;

    setMessage("");
    setFile(null);

    if (!selectedFile) return;

    const extension = selectedFile.name
      .slice(selectedFile.name.lastIndexOf("."))
      .toLowerCase();

    if (![".svg", ".png"].includes(extension)) {
      setMessage("Please select an SVG or PNG file.");
      setMessageType("error");
      event.target.value = "";
      return;
    }

    if (selectedFile.size > 2 * 1024 * 1024) {
      setMessage("The file must be smaller than 2 MB.");
      setMessageType("error");
      event.target.value = "";
      return;
    }

    setFile(selectedFile);
  }

  // UPLOAD STICKER
  async function handleUpload(event) {
    event.preventDefault();
    const form = event.currentTarget;
    setMessage("");

    if (!file) {
      setMessage("Please choose a file first.");
      setMessageType("error");
      return;
    }

    setUploading(true);

    try {
      const formData = new FormData();

      formData.append("file", file);
      formData.append("category", uploadCategory);

      const response = await fetch("/api/stickers", {
        method: "POST",
        body: formData,
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.error || "Upload failed.");
      }

      const refreshed = await loadLibrary();

      if (!refreshed) {
        throw new Error(
          "Sticker uploaded, but the gallery could not refresh."
        );
      }

      setBrowsePath(result.sticker.categoryPath);
      setCategory("All");
      setShowHidden(false);
      setSearchTerm("");
      setFile(null);

      form.reset();

      setMessage("Your sticker was uploaded successfully!");
      setMessageType("success");
    } catch (error) {
      setMessage(error.message || "Something went wrong.");
      setMessageType("error");
    } finally {
      setUploading(false);
    }
  }

  // CREATE NEW CATEGORY OR SUBCATEGORY
  async function handleCreateCategory(event) {
    event.preventDefault();
    setMessage("");

    if (!newCategory.trim()) {
      setMessage("Please enter a category name.");
      setMessageType("error");
      return;
    }

    setCreatingCategory(true);

    try {
      const response = await fetch("/api/stickers", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          action: "create-category",
          parentCategory,
          newCategory,
        }),
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(
          result.error || "Could not create category."
        );
      }

      const refreshed = await loadLibrary();

      if (!refreshed) {
        throw new Error(
          "Category created, but the gallery could not refresh."
        );
      }

      setUploadCategory(result.category.value);
      setParentCategory(result.category.value);
      setBrowsePath(result.category.value);
      setCategory("All");
      setNewCategory("");

      setMessage("Category created successfully!");
      setMessageType("success");
    } catch (error) {
      setMessage(error.message || "Something went wrong.");
      setMessageType("error");
    } finally {
      setCreatingCategory(false);
    }
  }

  return (
    <div className="w-full">
      {/* GALLERY HEADER */}
      <div className="mb-6">
        <h3 className="mb-2 font-heading text-2xl">
          Your stickers
        </h3>

        <p className="text-sm text-[var(--color-text-light)]">
          Drag stickers onto your website or your A4 sheet.
        </p>
      </div>

      {/* CREATE CATEGORY */}
      {showManagement && (
        <form
          onSubmit={handleCreateCategory}
          className="mb-5 rounded-2xl border border-[var(--color-border)] bg-white p-5"
        >
          <h4 className="mb-1 font-semibold">Create a category</h4>

          <p className="mb-4 text-sm text-[var(--color-text-light)]">
            Create folders and subcategories for your stickers.
          </p>

          <div className="flex flex-col gap-3">
            <label
              htmlFor="create-parent-category"
              className="text-sm font-medium"
            >
              Create inside
            </label>

            <select
              id="create-parent-category"
              value={parentCategory}
              onChange={(event) =>
                setParentCategory(event.target.value)
              }
              className="w-full rounded-xl border border-[var(--color-border)] bg-white px-4 py-3 text-sm"
            >
              {mainCategories.map((item) => (
                <option key={item} value={item}>
                  {formatCategory(item)}
                </option>
              ))}

              {categoryOptions.map((item) => (
                <option key={item.value} value={item.value}>
                  {formatCategory(item.value)}
                </option>
              ))}
            </select>

            <input
              type="text"
              value={newCategory}
              onChange={(event) => setNewCategory(event.target.value)}
              placeholder="New category name, e.g. Flowers"
              aria-label="New category name"
              className="w-full rounded-xl border border-[var(--color-border)] bg-white px-4 py-3 text-sm"
            />

            <button
              type="submit"
              disabled={creatingCategory || !newCategory.trim()}
              className="rounded-full border border-[var(--color-primary-dark)] px-6 py-3 text-sm font-medium transition hover:bg-[var(--color-surface)] disabled:opacity-50"
            >
              {creatingCategory ? "Creating..." : "+ Create category"}
            </button>
          </div>
        </form>
      )}

      {/* UPLOAD AREA */}
      {showManagement && (
        <form
          onSubmit={handleUpload}
          className="mb-7 rounded-2xl border border-dashed border-[var(--color-border)] bg-[var(--color-surface)] p-5"
        >
          <h4 className="mb-1 font-semibold">
            Add your own sticker
          </h4>

          <p className="mb-4 text-sm text-[var(--color-text-light)]">
            Upload your own SVG or PNG design.
          </p>

          <div className="flex flex-col gap-3">
            <label className="block cursor-pointer rounded-xl border border-[var(--color-border)] bg-white p-4 text-center transition hover:border-[var(--color-primary-dark)]">
              <span className="mb-2 block text-2xl">＋</span>

              <span className="block text-sm font-medium">
                Choose file from computer
              </span>

              <span className="mt-1 block text-xs text-[var(--color-text-light)]">
                SVG or PNG · Maximum 2 MB
              </span>

              <input
                type="file"
                accept=".svg,.png,image/svg+xml,image/png"
                onChange={handleFileChange}
                className="sr-only"
              />
            </label>

            {file && (
              <div className="rounded-xl bg-white px-4 py-3 text-sm">
                <span className="font-medium">Selected file:</span>
                <p className="mt-1 break-all text-[var(--color-text-light)]">
                  {file.name}
                </p>
              </div>
            )}

            <label
              htmlFor="upload-category"
              className="text-sm font-medium"
            >
              Save sticker in
            </label>

            <select
              id="upload-category"
              value={uploadCategory}
              onChange={(event) =>
                setUploadCategory(event.target.value)
              }
              className="w-full rounded-xl border border-[var(--color-border)] bg-white px-4 py-3 text-sm"
            >
              {mainCategories.map((item) => (
                <option key={item} value={item}>
                  {formatCategory(item)}
                </option>
              ))}

              {categoryOptions.map((item) => (
                <option key={item.value} value={item.value}>
                  {formatCategory(item.value)}
                </option>
              ))}
            </select>

            <button
              type="submit"
              disabled={uploading || !file}
              className="rounded-full bg-[var(--color-primary)] px-6 py-3 text-sm font-medium text-white transition hover:bg-[var(--color-primary-dark)] disabled:cursor-not-allowed disabled:opacity-50"
            >
              {uploading ? "Uploading..." : "Upload sticker"}
            </button>
          </div>
        </form>
      )}

      {/* STATUS MESSAGE */}
      {message && (
        <p
          role="status"
          className={`mb-5 text-sm ${
            messageType === "error"
              ? "text-red-600"
              : messageType === "success"
                ? "text-green-700"
                : "text-[var(--color-text-light)]"
          }`}
        >
          {message}
        </p>
      )}

      {/* SEARCH */}
      <div className="mb-5">
        <input
          type="search"
          value={searchTerm}
          onChange={(event) => setSearchTerm(event.target.value)}
          placeholder="Search stickers..."
          aria-label="Search stickers"
          className="w-full rounded-full border border-[var(--color-border)] bg-white px-5 py-3 text-sm outline-none transition focus:border-[var(--color-primary-dark)]"
        />
      </div>

      {/* GALLERY / HIDDEN TOGGLE */}
      <div className="mb-6 flex flex-wrap gap-2">
        <button
          type="button"
          onClick={() => {
            setShowHidden(false);
            setCategory("All");
            setBrowsePath(null);
          }}
          className={`rounded-full border px-4 py-2 text-sm transition ${
            !showHidden
              ? "border-[var(--color-primary-dark)] bg-[var(--color-primary-dark)] text-white"
              : "border-[var(--color-border)] bg-white hover:border-[var(--color-primary-dark)]"
          }`}
        >
          Gallery
        </button>

        <button
          type="button"
          onClick={() => setShowHidden(true)}
          className={`rounded-full border px-4 py-2 text-sm transition ${
            showHidden
              ? "border-[var(--color-primary-dark)] bg-[var(--color-primary-dark)] text-white"
              : "border-[var(--color-border)] bg-white hover:border-[var(--color-primary-dark)]"
          }`}
        >
          Hidden ({hiddenStickers.length})
        </button>
      </div>

      {!showHidden ? (
        <>
          {/* CATEGORY NAVIGATION */}
          <div className="mb-6 space-y-3">
            {/* MAIN CATEGORIES */}
            <div className="flex flex-wrap gap-2">
              {mainCategories.map((item) => (
                <button
                  key={item}
                  type="button"
                  onClick={() => selectMainCategory(item)}
                  className={`rounded-full border px-4 py-2 text-sm transition ${
                    browsePath?.split("/")[0] === item
                      ? "border-[var(--color-primary-dark)] bg-[var(--color-primary-dark)] text-white"
                      : "border-[var(--color-border)] bg-white hover:border-[var(--color-primary-dark)]"
                  }`}
                >
                  {formatCategory(item)}
                </button>
              ))}
            </div>

            {/* SUBCATEGORY ROWS */}
            {categoryRows.map((row) => (
              <div
                key={row.parent}
                className="flex flex-wrap items-center gap-2 pl-3"
              >
                <span className="mr-1 text-sm text-[var(--color-text-light)]">
                  ↳
                </span>

                {row.items.map((item) => (
                  <button
                    key={item.value}
                    type="button"
                    onClick={() => openCategory(item.value)}
                    className={`rounded-full border px-4 py-2 text-sm transition ${
                      browsePath === item.value
                        ? "border-[var(--color-primary-dark)] bg-[var(--color-primary-dark)] text-white"
                        : "border-[var(--color-border)] bg-white hover:border-[var(--color-primary-dark)]"
                    }`}
                  >
                    {formatCategory(item.value.split("/").pop())}
                  </button>
                ))}
              </div>
            ))}

            {browsePath && (
              <button
                type="button"
                onClick={() => {
                  setBrowsePath(null);
                  setCategory("All");
                  setSearchTerm("");
                }}
                className="text-sm font-medium text-[var(--color-primary-dark)] hover:underline"
              >
                ← All categories
              </button>
            )}
          </div>

          {/* FAVORITES FILTER */}
          <div className="mb-5">
            <button
              type="button"
              onClick={() => {
                setCategory(
                  category === "Favorites" ? "All" : "Favorites"
                );
              }}
              className={`rounded-full border px-4 py-2 text-sm transition ${
                category === "Favorites"
                  ? "border-[var(--color-primary-dark)] bg-[var(--color-primary-dark)] text-white"
                  : "border-[var(--color-border)] bg-white hover:border-[var(--color-primary-dark)]"
              }`}
            >
              ♥ Favorites
            </button>
          </div>

          {/* VISIBLE STICKERS */}
          {loadingLibrary ? (
            <p className="py-8 text-center text-sm text-[var(--color-text-light)]">
              Loading stickers...
            </p>
          ) : filteredStickers.length > 0 ? (
            <>
              <h4 className="mb-4 font-semibold">
                {category === "Favorites"
                  ? "Your favorite stickers"
                  : browsePath
                    ? `Stickers in ${formatCategory(browsePath)}`
                    : "All stickers"}
              </h4>

              <div className="grid grid-cols-2 gap-4 sm:grid-cols-3">
                {filteredStickers.map((sticker) => (
                  <StickerCard
                    key={sticker.id}
                    sticker={sticker}
                    onSelect={onSelectSticker}
                    isFavorite={favorites.includes(sticker.id)}
                    onToggleFavorite={toggleFavorite}
                    onHide={() =>
                      hideStickerFromGallery(sticker.id)
                    }
                  />
                ))}
              </div>
            </>
          ) : (
            <div className="rounded-2xl border border-dashed border-[var(--color-border)] p-8 text-center">
              <p className="text-sm text-[var(--color-text-light)]">
                {category === "Favorites"
                  ? "You have no favorite stickers yet."
                  : browsePath
                    ? "No stickers in this folder yet."
                    : "Choose a category to see your stickers."}
              </p>
            </div>
          )}
        </>
      ) : (
        <>
          <p className="mb-5 text-sm text-[var(--color-text-light)]">
            Hidden stickers are still saved in your folders. Restore one
            to show it in the gallery again.
          </p>

          {filteredHiddenStickers.length > 0 ? (
            <div className="grid grid-cols-2 gap-4 sm:grid-cols-3">
              {filteredHiddenStickers.map((sticker) => (
                <div
                  key={sticker.id}
                  className="rounded-2xl border border-[var(--color-border)] bg-white p-3"
                >
                  <div className="flex aspect-square items-center justify-center p-3">
                    <img
                      src={sticker.src}
                      alt={sticker.name}
                      className="h-full w-full object-contain"
                    />
                  </div>

                  <p className="mb-3 truncate text-center text-sm font-medium capitalize">
                    {sticker.name}
                  </p>

                  <button
                    type="button"
                    onClick={() =>
                      restoreStickerToGallery(sticker.id)
                    }
                    className="w-full rounded-full border border-[var(--color-border)] px-3 py-2 text-sm transition hover:border-[var(--color-primary-dark)] hover:bg-[var(--color-surface)]"
                  >
                    Restore to gallery
                  </button>
                </div>
              ))}
            </div>
          ) : (
            <div className="rounded-2xl border border-dashed border-[var(--color-border)] p-8 text-center">
              <p className="text-sm text-[var(--color-text-light)]">
                No hidden stickers.
              </p>
            </div>
          )}
        </>
      )}
    </div>
  );
}
